/**
 * Generate the editor's TypeScript types from the converter's JSON Schemas, so
 * the editor and the converter cannot drift apart:
 *
 *   ../tests/golden-editor/ir.schema.json      -> src/generated/ir.ts       (Html2LvglIR, Node)
 *   ../src/schemas/registry-export.schema.json -> src/generated/registry.ts (Html2LvglRegistryExport)
 *   ../src/schemas/sidecar.schema.json         -> src/generated/sidecar.ts  (Html2LvglSidecarOverrides)
 *
 * The root type is named from each schema's `title`.
 *
 * Run `npm run generate:types` after changing a schema. The generated files are
 * committed, and tests/generated-types.test.ts fails when they are stale.
 */
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { compile } from 'json-schema-to-typescript';

const editorRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const repoRoot = resolve(editorRoot, '..');

/** @type {{ schema: string, output: string }[]} */
export const TARGETS = [
  { schema: 'tests/golden-editor/ir.schema.json', output: 'src/generated/ir.ts' },
  { schema: 'src/schemas/registry-export.schema.json', output: 'src/generated/registry.ts' },
  { schema: 'src/schemas/sidecar.schema.json', output: 'src/generated/sidecar.ts' },
];

/**
 * Compile every schema.
 *
 * @returns {Promise<Record<string, string>>} Output path (relative to the editor) to file text.
 */
export async function generateAll() {
  /** @type {Record<string, string>} */
  const files = {};
  for (const { schema, output } of TARGETS) {
    const schemaPath = join(repoRoot, schema);
    let parsed;
    try {
      parsed = JSON.parse(readFileSync(schemaPath, 'utf8'));
    } catch (err) {
      throw new Error(`cannot read the schema ${schemaPath}: ${err instanceof Error ? err.message : String(err)}`);
    }
    const banner = `/* Generated by scripts/generate-types.mjs from ${schema}. Do not edit; run \`npm run generate:types\`. */`;
    const body = await compile(parsed, 'Schema', {
      bannerComment: banner,
      additionalProperties: false,
      cwd: dirname(schemaPath),
      format: true,
      style: { singleQuote: true, semi: true, printWidth: 100 },
      declareExternallyReferenced: true,
    });
    files[output] = body;
  }
  return files;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const files = await generateAll();
  for (const [output, text] of Object.entries(files)) {
    const path = join(editorRoot, output);
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, text);
    console.log(`wrote ${output}`);
  }
}
